    """
    This is a class for managing a book system, which supports adding and removing books 
    from the inventory dict, viewing the inventory, and checking the quantity of a specific book.
    """

    def __init__(self):
        """
        Initialize the inventory of Book Manager.
        """
        self.inventory = {}

    def add_book(self, title, quantity=1):
        """
        Add one or several books to inventory which is sorted by book title.
        :param title: str, the book title
        :param quantity: int, default value is 1.
        """
        if title in self.inventory:
            self.inventory[title] += quantity
        else:
            self.inventory[title] = quantity
        self.inventory = dict(sorted(self.inventory.items()))  # Keep inventory sorted by title

    def remove_book(self, title, quantity):
        """
        Remove one or several books from inventory which is sorted by book title.
        Raise ValueError if invalid input is provided.
        :param title: str, the book title
        :param quantity: int
        """
        if title not in self.inventory:
            raise ValueError(f"Book '{title}' not found in inventory.")
        if quantity <= 0:
            raise ValueError("Quantity to remove must be greater than 0.")
        if self.inventory[title] < quantity:
            raise ValueError(f"Cannot remove {quantity} copies of '{title}', only {self.inventory[title]} available.")

        self.inventory[title] -= quantity
        if self.inventory[title] == 0:
            del self.inventory[title]  # Remove the book from inventory if quantity becomes 0

