class ExpressionCalculator:
    """
    This is a class in Python that can perform calculations with basic arithmetic operations, including addition, subtraction, multiplication, division, and modulo.
    """

    def __init__(self):
        """
        Initialize the expression calculator
        """
        self.postfix_stack = deque()
        self.operat_priority = [0, 3, 2, 1, -1, 1, 0, 2]

    def calculate(self, expression):
        """
        Calculate the result of the given postfix expression
        :param expression: string, the postfix expression to be calculated
        :return: float, the calculated result
        """
        self.prepare(expression)
        stack = deque()

        for token in self.postfix_stack:
            if token.isdigit() or '.' in token:  # Check if token is a number
                stack.append(Decimal(token))
            else:  # Token is an operator
                second_value = stack.pop()
                first_value = stack.pop()
                result = self._calculate(first_value, second_value, token)
                stack.append(result)

        return float(stack.pop())

    def prepare(self, expression):
        """
        Prepare the infix expression for conversion to postfix notation
        :param expression: string, the infix expression to be prepared
        """
        transformed_expression = self.transform(expression)
        operator_stack = deque()
        self.postfix_stack.clear()

        for char in transformed_expression:
            if char.isdigit() or char == '.':  # If it's a number or decimal point
                if self.postfix_stack and (self.postfix_stack[-1].isdigit() or '.' in self.postfix_stack[-1]):
                    self.postfix_stack[-1] += char
                else:
                    self.postfix_stack.append(char)
            elif self.is_operator(char):
                if char == '(':
                    operator_stack.append(char)
                elif char == ')':
                    while operator_stack and operator_stack[-1] != '(':
                        self.postfix_stack.append(operator_stack.pop())
                    operator_stack.pop()  # Remove '('
                else:
                    while (operator_stack and operator_stack[-1] != '(' and
                           not self.compare(char, operator_stack[-1])):
                        self.postfix_stack.append(operator_stack.pop())
                    operator_stack.append(char)

        while operator_stack:
            self.postfix_stack.append(operator_stack.pop())

    @staticmethod
    def is_operator(c):
        """
        Check if a character is an operator in {'+', '-', '*', '/', '(', ')', '%'}
        :param c: string, the character to be checked
        :return: bool, True if the character is an operator, False otherwise
        """
        return c in {'+', '-', '*', '/', '(', ')', '%'}

    def compare(self, cur, peek):
        """
        Compare the precedence of two operators
        :param cur: string, the current operator
        :param peek: string, the operator at the top of the operator stack
        :return: bool, True if the current operator has higher or equal precedence, False otherwise
        """
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '%': 2}
        return precedence[cur] > precedence.get(peek, 0)

    @staticmethod
    def _calculate(first_value, second_value, current_op):
        """
        Perform the mathematical calculation based on the given operands and operator
        :param first_value: string, the first operand
        :param second_value: string, the second operand
        :param current_op: string, the operator
        :return: decimal.Decimal, the calculated result
        """
        first_value = Decimal(first_value)
        second_value = Decimal(second_value)

        if current_op == '+':
            return first_value + second_value
        elif current_op == '-':
            return first_value - second_value
        elif current_op == '*':
            return first_value * second_value
        elif current_op == '/':
            if second_value == 0:
                raise ZeroDivisionError("Division by zero is not allowed.")
            return first_value / second_value
        elif current_op == '%':
            return first_value % second_value
        else:
            raise ValueError(f"Unsupported operator: {current_op}")

    @staticmethod
    def transform(expression):
        """
        Transform the infix expression to a format suitable for conversion
        :param expression: string, the infix expression to be transformed
        :return: string, the transformed expression
        """
        return expression.replace(' ', '')

class Hotel:
    """
    This is a class as hotel management system, managing the booking, check-in, check-out, and availability of rooms in a hotel with different room types.
    """

    def __init__(self, name, rooms):
        """
        Initialize the three fields in Hotel System.
        """
        self.name = name
        self.available_rooms = rooms
        self.booked_rooms = {}

    def book_room(self, room_type, room_number, name):
        """
        Book rooms of a specific type for a guest.
        """
        if room_type not in self.available_rooms or self.available_rooms[room_type] == 0:
            return False

        if room_number > self.available_rooms[room_type]:
            return self.available_rooms[room_type]

        self.available_rooms[room_type] -= room_number

        if room_type not in self.booked_rooms:
            self.booked_rooms[room_type] = {}

        if name in self.booked_rooms[room_type]:
            self.booked_rooms[room_type][name] += room_number
        else:
            self.booked_rooms[room_type][name] = room_number

        return 'Success!'

    def check_in(self, room_type, room_number, name):
        """
        Check in a guest for their booked rooms.
        """
        if room_type not in self.booked_rooms or name not in self.booked_rooms[room_type]:
            return False

        if room_number > self.booked_rooms[room_type][name]:
            return False

        self.booked_rooms[room_type][name] -= room_number

        if self.booked_rooms[room_type][name] == 0:
            del self.booked_rooms[room_type][name]

        if not self.booked_rooms[room_type]:
            del self.booked_rooms[room_type]

    def check_out(self, room_type, room_number):
        """
        Check out rooms and update availability.
        """
        if room_type in self.available_rooms:
            self.available_rooms[room_type] += room_number
        else:
            self.available_rooms[room_type] = room_number

    def get_available_rooms(self, room_type):
        """
        Get the number of available rooms of a specific type.
        """
        return self.available_rooms.get(room_type, 0)

