class MetricsCalculator2:
    """
    The class provides to calculate Mean Reciprocal Rank (MRR) and Mean Average Precision (MAP) based on input data, 
    where MRR measures the ranking quality and MAP measures the average precision.
    """

    def __init__(self):
        pass

    @staticmethod
    def mrr(data):
        """
        Compute the MRR of the input data. MRR is a widely used evaluation index. It is the mean of reciprocal rank.
        :param data: the data must be a tuple or list of tuples. Each tuple is of the form ([1, 0, ...], ground_truth_num).
                     1 stands for a correct answer, 0 stands for a wrong answer.
        :return: If input data is a single tuple, return the MRR for that tuple. If input data is a list of tuples, 
                 return the average MRR for all tuples and a list of MRR values for each tuple.
        """
        def calculate_single_mrr(single_data):
            results, _ = single_data
            for idx, val in enumerate(results):
                if val == 1:
                    return 1 / (idx + 1)
            return 0

        if isinstance(data, tuple):
            return calculate_single_mrr(data), [calculate_single_mrr(data)]
        elif isinstance(data, list):
            mrr_values = [calculate_single_mrr(d) for d in data]
            return np.mean(mrr_values), mrr_values

    @staticmethod
    def map(data):
        """
        Compute the MAP of the input data. MAP is a widely used evaluation index. It is the mean of AP (average precision).
        :param data: the data must be a tuple or list of tuples. Each tuple is of the form ([1, 0, ...], ground_truth_num).
                     1 stands for a correct answer, 0 stands for a wrong answer.
        :return: If input data is a single tuple, return the MAP for that tuple. If input data is a list of tuples, 
                 return the average MAP for all tuples and a list of MAP values for each tuple.
        """
        def calculate_single_map(single_data):
            results, ground_truth_num = single_data
            if ground_truth_num == 0:
                return 0
            precision_at_k = []
            correct_count = 0
            for idx, val in enumerate(results):
                if val == 1:
                    correct_count += 1
                    precision_at_k.append(correct_count / (idx + 1))
            return np.sum(precision_at_k) / ground_truth_num if ground_truth_num > 0 else 0

        if isinstance(data, tuple):
            return calculate_single_map(data), [calculate_single_map(data)]
        elif isinstance(data, list):
            map_values = [calculate_single_map(d) for d in data]
            return np.mean(map_values), map_values

class NumberWordFormatter:
    """
    This is a class that provides to convert numbers into their corresponding English word representation, including handling the conversion of both the integer and decimal parts, and incorporating appropriate connectors and units.
    """

    def __init__(self):
        """
        Initialize NumberWordFormatter object.
        """
        self.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        self.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN", "NINETEEN"]
        self.NUMBER_TEN = ["", "TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        self.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        self.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]

    def format(self, x):
        """
        Converts a number into words format
        :param x: int or float, the number to be converted into words format
        :return: str, the number in words format
        """
        if isinstance(x, float):
            integer_part, decimal_part = str(x).split(".")
            integer_words = self.format_string(integer_part)
            decimal_words = " ".join([self.NUMBER[int(d)] for d in decimal_part])
            return f"{integer_words} POINT {decimal_words} ONLY"
        elif isinstance(x, int):
            return self.format_string(str(x))
        else:
            raise ValueError("Input must be an integer or float.")

    def format_string(self, x):
        """
        Converts a string representation of a number into words format
        :param x: str, the string representation of a number
        :return: str, the number in words format
        """
        if not x.isdigit():
            raise ValueError("Input must be a string representation of a number.")

        x = x.lstrip("0")  # Remove leading zeros
        if not x:
            return "ZERO ONLY"

        parts = []
        x = x[::-1]  # Reverse the string for easier processing
        for i in range(0, len(x), 3):
            chunk = x[i:i+3][::-1]  # Process three digits at a time
            if chunk != "000":
                parts.append(self.trans_three(chunk) + (f" {self.parse_more(i // 3)}" if i // 3 > 0 else ""))

        result = " ".join(reversed(parts)).strip()
        return f"{result} ONLY"

    def trans_two(self, s):
        """
        Converts a two-digit number into words format
        :param s: str, the two-digit number
        :return: str, the number in words format
        """
        if len(s) == 1:
            return self.NUMBER[int(s)]
        elif s[0] == "1":
            return self.NUMBER_TEEN[int(s[1])]
        elif s[0] == "0":
            return self.NUMBER[int(s[1])]
        else:
            return f"{self.NUMBER_TEN[int(s[0])]} {self.NUMBER[int(s[1])]}".strip()

    def trans_three(self, s):
        """
        Converts a three-digit number into words format
        :param s: str, the three-digit number
        :return: str, the number in words format
        """
        if len(s) == 3 and s[0] != "0":
            return f"{self.NUMBER[int(s[0])]} HUNDRED AND {self.trans_two(s[1:])}".strip(" AND ")
        elif len(s) == 2:
            return self.trans_two(s)
        elif len(s) == 1:
            return self.NUMBER[int(s)]
        else:
            return ""

    def parse_more(self, i):
        """
        Parses the thousand/million/billion suffix based on the index
        :param i: int, the index representing the magnitude (thousand, million, billion)
        :return: str, the corresponding suffix for the magnitude
        """
        return self.NUMBER_MORE[i] if i < len(self.NUMBER_MORE) else ""

